/// The bra x ket R matrix of `l_ab = 0`, `l_cd = 0`: 1 x 1, one column per ket Hermite function in
/// `hermite_index` order, the signs and `pref` included.
#[inline(always)]
pub fn r_matrix_0_0<'c>(boys: &[f64], pcx: f64, pcy: f64, pcz: f64, pref: f64, mut columns: impl Iterator<Item = &'c mut [f64]>) {
    let boys = &boys[..1];
    let mref = -pref;
    {
        let c = &mut columns.next().expect("one column per ket Hermite function")[..1];
        c[0] = pref * boys[0];
    }
}

