    let r2_3_0_0 = pcx * r3_2_0_0 + 2.0 * r3_1_0_0;
    let r1_4_0_0 = pcx * r2_3_0_0 + 3.0 * r2_2_0_0;
    let r0_5_0_0 = pcx * r1_4_0_0 + 4.0 * r1_3_0_0;
    let r4_0_1_0 = pcy * boys[5];
