    let r2_1_1_0 = pcx * r3_0_1_0;
    let r1_2_1_0 = pcx * r2_1_1_0 + 1.0 * r2_0_1_0;
    let r0_3_1_0 = pcx * r1_2_1_0 + 2.0 * r1_1_1_0;
    let r0_0_2_0 = pcy * r1_0_1_0 + 1.0 * boys[1];
    let r1_0_2_0 = pcy * r2_0_1_0 + 1.0 * boys[2];
    let r0_1_2_0 = pcx * r1_0_2_0;
    let r2_0_2_0 = pcy * r3_0_1_0 + 1.0 * boys[3];
    let r1_1_2_0 = pcx * r2_0_2_0;
    let r0_2_2_0 = pcx * r1_1_2_0 + 1.0 * r1_0_2_0;
    let r0_0_3_0 = pcy * r1_0_2_0 + 2.0 * r1_0_1_0;
    let r1_0_3_0 = pcy * r2_0_2_0 + 2.0 * r2_0_1_0;
