    let r0_1_0_1 = pcx * r1_0_0_1;
    let r2_0_0_1 = pcz * boys[3];
    let r1_1_0_1 = pcx * r2_0_0_1;
    let r0_2_0_1 = pcx * r1_1_0_1 + 1.0 * r1_0_0_1;
    let r3_0_0_1 = pcz * boys[4];
    let r2_1_0_1 = pcx * r3_0_0_1;
    let r1_2_0_1 = pcx * r2_1_0_1 + 1.0 * r2_0_0_1;
    let r0_3_0_1 = pcx * r1_2_0_1 + 2.0 * r1_1_0_1;
